-- DEMONSTRAÇÃO SINTÉTICA. Projeções de leitura R01–R06, sem novas fórmulas.
CREATE SCHEMA vrac_app;
REVOKE ALL ON SCHEMA vrac_app FROM PUBLIC, anon, authenticated;
GRANT USAGE ON SCHEMA vrac_app TO authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA vrac_app REVOKE ALL ON TABLES FROM PUBLIC, anon, authenticated;
CREATE TABLE vrac_app.departments (department text PRIMARY KEY);
CREATE TABLE vrac_app.access_grants (user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, department text NOT NULL REFERENCES vrac_app.departments(department), enabled boolean NOT NULL DEFAULT true, PRIMARY KEY(user_id, department));
CREATE TABLE vrac_app.dataset_metadata (singleton boolean PRIMARY KEY CHECK(singleton), synthetic boolean NOT NULL CHECK(synthetic), version text NOT NULL, seed bigint NOT NULL, periods text[] NOT NULL, policy jsonb NOT NULL);
CREATE TABLE vrac_app."register" (scope_department text NOT NULL REFERENCES vrac_app.departments(department), ordinal integer NOT NULL CHECK(ordinal >= 0), "department" text, "registration" text, "registration_int" bigint, "person_key" text, "name" text, "cadre" text, "category" text, "status" text, "dual_role" text, "extraordinary" text, "weekly_hours" double precision, "tenure_years" double precision, "degree" text, PRIMARY KEY(scope_department, ordinal));
CREATE TABLE vrac_app."real_hours" (scope_department text NOT NULL REFERENCES vrac_app.departments(department), ordinal integer NOT NULL CHECK(ordinal >= 0), "registration_int" bigint, "semester" bigint, "hours" double precision, "cadre" text, PRIMARY KEY(scope_department, ordinal));
CREATE TABLE vrac_app."history" (scope_department text NOT NULL REFERENCES vrac_app.departments(department), ordinal integer NOT NULL CHECK(ordinal >= 0), "department" text, "person_key" text, "registration" text, "reference_date" timestamp without time zone, "cadre" text, "category" text, "status" text, "payroll_batch" text, "leave_code" text, PRIMARY KEY(scope_department, ordinal));
CREATE TABLE vrac_app."workloads" (scope_department text NOT NULL REFERENCES vrac_app.departments(department), ordinal integer NOT NULL CHECK(ordinal >= 0), "department" text, "registration" text, "semester" bigint, "name" text, "cadre" text, "category" text, "real_hours" double precision, "contracted_hours" double precision, PRIMARY KEY(scope_department, ordinal));
CREATE TABLE vrac_app."allocations" (scope_department text NOT NULL REFERENCES vrac_app.departments(department), ordinal integer NOT NULL CHECK(ordinal >= 0), "department" text, "teaching_department" text, "registration" text, "semester" bigint, "discipline" text, "class_id" text, "allocated_hours" double precision, "vacancies_filled" bigint, "shared" text, "classification" text, PRIMARY KEY(scope_department, ordinal));
CREATE TABLE vrac_app."functions" (scope_department text NOT NULL REFERENCES vrac_app.departments(department), ordinal integer NOT NULL CHECK(ordinal >= 0), "department" text, "distribution_department" text, "registration" text, "year" bigint, "month" bigint, "description" text, "role" text, PRIMARY KEY(scope_department, ordinal));
CREATE TABLE vrac_app."appointments" (scope_department text NOT NULL REFERENCES vrac_app.departments(department), ordinal integer NOT NULL CHECK(ordinal >= 0), "department" text, "registration" text, "role" text, "start" timestamp without time zone, "end" timestamp without time zone, "evidence" text, "administrative" boolean, PRIMARY KEY(scope_department, ordinal));
CREATE TABLE vrac_app."students" (scope_department text NOT NULL REFERENCES vrac_app.departments(department), ordinal integer NOT NULL CHECK(ordinal >= 0), "registration" bigint, "department" text, "course" text, "course_name" text, "qualification" text, "shift" text, "level" text, "entry_period" bigint, "period" bigint, "status" text, "entry_kind" text, PRIMARY KEY(scope_department, ordinal));
CREATE TABLE vrac_app."student_history" (scope_department text NOT NULL REFERENCES vrac_app.departments(department), ordinal integer NOT NULL CHECK(ordinal >= 0), "registration" bigint, "department" text, "course" text, "course_name" text, "qualification" text, "shift" text, "level" text, "entry_period" bigint, "period" bigint, "status" text, "entry_kind" text, PRIMARY KEY(scope_department, ordinal));
CREATE TABLE vrac_app."scholarships" (scope_department text NOT NULL REFERENCES vrac_app.departments(department), ordinal integer NOT NULL CHECK(ordinal >= 0), "registration" bigint, "period" bigint, PRIMARY KEY(scope_department, ordinal));
CREATE TABLE vrac_app."demo_faculty" (scope_department text NOT NULL REFERENCES vrac_app.departments(department), ordinal integer NOT NULL CHECK(ordinal >= 0), "department" text, "period" text, "reference_month" text, "teacher_id" text, "contract_id" text, "employment_type" text, "real_hours" double precision, PRIMARY KEY(scope_department, ordinal));
CREATE TABLE vrac_app."demo_allocations" (scope_department text NOT NULL REFERENCES vrac_app.departments(department), ordinal integer NOT NULL CHECK(ordinal >= 0), "department" text, "teaching_department" text, "period" text, "teacher_id" text, "class_id" text, "curriculum_id" text, "sharing_id" text, "allocated_hours" double precision, "students" bigint, "classification" text, PRIMARY KEY(scope_department, ordinal));
ALTER TABLE vrac_app."access_grants" ENABLE ROW LEVEL SECURITY;
ALTER TABLE vrac_app."access_grants" FORCE ROW LEVEL SECURITY;
REVOKE ALL ON vrac_app."access_grants" FROM PUBLIC, anon, authenticated;
GRANT SELECT ON vrac_app."access_grants" TO authenticated;
CREATE POLICY read_authorized ON vrac_app."access_grants" FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid()) AND enabled AND COALESCE((SELECT auth.jwt()->>'is_anonymous'), 'false') = 'false');
ALTER TABLE vrac_app."departments" ENABLE ROW LEVEL SECURITY;
ALTER TABLE vrac_app."departments" FORCE ROW LEVEL SECURITY;
REVOKE ALL ON vrac_app."departments" FROM PUBLIC, anon, authenticated;
GRANT SELECT ON vrac_app."departments" TO authenticated;
CREATE POLICY read_authorized ON vrac_app."departments" FOR SELECT TO authenticated USING (department IN (SELECT department FROM vrac_app.access_grants) AND COALESCE((SELECT auth.jwt()->>'is_anonymous'), 'false') = 'false');
ALTER TABLE vrac_app."dataset_metadata" ENABLE ROW LEVEL SECURITY;
ALTER TABLE vrac_app."dataset_metadata" FORCE ROW LEVEL SECURITY;
REVOKE ALL ON vrac_app."dataset_metadata" FROM PUBLIC, anon, authenticated;
GRANT SELECT ON vrac_app."dataset_metadata" TO authenticated;
CREATE POLICY read_authorized ON vrac_app."dataset_metadata" FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM vrac_app.access_grants) AND COALESCE((SELECT auth.jwt()->>'is_anonymous'), 'false') = 'false');
