CREATE POLICY read_authorized ON vrac_app."register" FOR SELECT TO authenticated USING (scope_department IN (SELECT department FROM vrac_app.access_grants) AND COALESCE((SELECT auth.jwt()->>'is_anonymous'), 'false') = 'false');
