CREATE FUNCTION public.vrac_options() RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path = '' AS $$
SELECT COALESCE((SELECT jsonb_build_object('synthetic', synthetic, 'version', version, 'periods', periods, 'departments', (SELECT COALESCE(jsonb_agg(department ORDER BY department), '[]'::jsonb) FROM vrac_app.departments)) FROM vrac_app.dataset_metadata), '{"synthetic":true,"departments":[],"periods":[]}'::jsonb); $$;
REVOKE ALL ON FUNCTION public.vrac_options() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.vrac_options() TO authenticated;
CREATE FUNCTION public.vrac_snapshot(p_departments text[]) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path = '' SET statement_timeout = '15s' AS $$
DECLARE result jsonb; BEGIN
IF p_departments IS NULL OR cardinality(p_departments) NOT BETWEEN 1 AND 1000 OR EXISTS (SELECT 1 FROM unnest(p_departments) d WHERE d IS NULL OR d NOT IN (SELECT department FROM vrac_app.departments)) OR cardinality(p_departments) <> (SELECT count(DISTINCT d) FROM unnest(p_departments) d) THEN RAISE EXCEPTION 'Recorte não autorizado' USING ERRCODE = '42501'; END IF;
IF (SELECT count(*) FROM vrac_app."register" WHERE scope_department = ANY(p_departments)) > 5000 THEN RAISE EXCEPTION 'Limite do snapshot excedido'; END IF;
IF (SELECT count(*) FROM vrac_app."real_hours" WHERE scope_department = ANY(p_departments)) > 5000 THEN RAISE EXCEPTION 'Limite do snapshot excedido'; END IF;
IF (SELECT count(*) FROM vrac_app."history" WHERE scope_department = ANY(p_departments)) > 5000 THEN RAISE EXCEPTION 'Limite do snapshot excedido'; END IF;
IF (SELECT count(*) FROM vrac_app."workloads" WHERE scope_department = ANY(p_departments)) > 5000 THEN RAISE EXCEPTION 'Limite do snapshot excedido'; END IF;
IF (SELECT count(*) FROM vrac_app."allocations" WHERE scope_department = ANY(p_departments)) > 5000 THEN RAISE EXCEPTION 'Limite do snapshot excedido'; END IF;
IF (SELECT count(*) FROM vrac_app."functions" WHERE scope_department = ANY(p_departments)) > 5000 THEN RAISE EXCEPTION 'Limite do snapshot excedido'; END IF;
IF (SELECT count(*) FROM vrac_app."appointments" WHERE scope_department = ANY(p_departments)) > 5000 THEN RAISE EXCEPTION 'Limite do snapshot excedido'; END IF;
IF (SELECT count(*) FROM vrac_app."students" WHERE scope_department = ANY(p_departments)) > 5000 THEN RAISE EXCEPTION 'Limite do snapshot excedido'; END IF;
IF (SELECT count(*) FROM vrac_app."student_history" WHERE scope_department = ANY(p_departments)) > 5000 THEN RAISE EXCEPTION 'Limite do snapshot excedido'; END IF;
IF (SELECT count(*) FROM vrac_app."scholarships" WHERE scope_department = ANY(p_departments)) > 5000 THEN RAISE EXCEPTION 'Limite do snapshot excedido'; END IF;
IF (SELECT count(*) FROM vrac_app."demo_faculty" WHERE scope_department = ANY(p_departments)) > 5000 THEN RAISE EXCEPTION 'Limite do snapshot excedido'; END IF;
IF (SELECT count(*) FROM vrac_app."demo_allocations" WHERE scope_department = ANY(p_departments)) > 5000 THEN RAISE EXCEPTION 'Limite do snapshot excedido'; END IF;
SELECT jsonb_build_object('synthetic', synthetic, 'version', version, 'periods', periods, 'policy', policy) INTO STRICT result FROM vrac_app.dataset_metadata;
result := result || jsonb_build_object('register', (SELECT COALESCE(jsonb_agg(to_jsonb(r) - 'scope_department' - 'ordinal' ORDER BY scope_department, ordinal), '[]'::jsonb) FROM vrac_app."register" r WHERE scope_department = ANY(p_departments)));
result := result || jsonb_build_object('real_hours', (SELECT COALESCE(jsonb_agg(to_jsonb(r) - 'scope_department' - 'ordinal' ORDER BY scope_department, ordinal), '[]'::jsonb) FROM vrac_app."real_hours" r WHERE scope_department = ANY(p_departments)));
result := result || jsonb_build_object('history', (SELECT COALESCE(jsonb_agg(to_jsonb(r) - 'scope_department' - 'ordinal' ORDER BY scope_department, ordinal), '[]'::jsonb) FROM vrac_app."history" r WHERE scope_department = ANY(p_departments)));
result := result || jsonb_build_object('workloads', (SELECT COALESCE(jsonb_agg(to_jsonb(r) - 'scope_department' - 'ordinal' ORDER BY scope_department, ordinal), '[]'::jsonb) FROM vrac_app."workloads" r WHERE scope_department = ANY(p_departments)));
result := result || jsonb_build_object('allocations', (SELECT COALESCE(jsonb_agg(to_jsonb(r) - 'scope_department' - 'ordinal' ORDER BY scope_department, ordinal), '[]'::jsonb) FROM vrac_app."allocations" r WHERE scope_department = ANY(p_departments)));
result := result || jsonb_build_object('functions', (SELECT COALESCE(jsonb_agg(to_jsonb(r) - 'scope_department' - 'ordinal' ORDER BY scope_department, ordinal), '[]'::jsonb) FROM vrac_app."functions" r WHERE scope_department = ANY(p_departments)));
result := result || jsonb_build_object('appointments', (SELECT COALESCE(jsonb_agg(to_jsonb(r) - 'scope_department' - 'ordinal' ORDER BY scope_department, ordinal), '[]'::jsonb) FROM vrac_app."appointments" r WHERE scope_department = ANY(p_departments)));
result := result || jsonb_build_object('students', (SELECT COALESCE(jsonb_agg(to_jsonb(r) - 'scope_department' - 'ordinal' ORDER BY scope_department, ordinal), '[]'::jsonb) FROM vrac_app."students" r WHERE scope_department = ANY(p_departments)));
result := result || jsonb_build_object('student_history', (SELECT COALESCE(jsonb_agg(to_jsonb(r) - 'scope_department' - 'ordinal' ORDER BY scope_department, ordinal), '[]'::jsonb) FROM vrac_app."student_history" r WHERE scope_department = ANY(p_departments)));
result := result || jsonb_build_object('scholarships', (SELECT COALESCE(jsonb_agg(to_jsonb(r) - 'scope_department' - 'ordinal' ORDER BY scope_department, ordinal), '[]'::jsonb) FROM vrac_app."scholarships" r WHERE scope_department = ANY(p_departments)));
result := result || jsonb_build_object('demo_faculty', (SELECT COALESCE(jsonb_agg(to_jsonb(r) - 'scope_department' - 'ordinal' ORDER BY scope_department, ordinal), '[]'::jsonb) FROM vrac_app."demo_faculty" r WHERE scope_department = ANY(p_departments)));
result := result || jsonb_build_object('demo_allocations', (SELECT COALESCE(jsonb_agg(to_jsonb(r) - 'scope_department' - 'ordinal' ORDER BY scope_department, ordinal), '[]'::jsonb) FROM vrac_app."demo_allocations" r WHERE scope_department = ANY(p_departments)));
RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.vrac_snapshot(text[]) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.vrac_snapshot(text[]) TO authenticated;
NOTIFY pgrst, 'reload schema';
